#!/usr/bin/env bash
# Renders config.js into the built web distribution.
# Usage: COEXIST_FIREBASE_API_KEY=... scripts/render_web_config.sh [dist_dir]
set -euo pipefail

DIST_DIR="${1:-shared/build/dist/js/productionExecutable}"
: "${COEXIST_FIREBASE_API_KEY:?COEXIST_FIREBASE_API_KEY is required}"

if [[ ! "$COEXIST_FIREBASE_API_KEY" =~ ^[A-Za-z0-9_-]+$ ]]; then
  echo "COEXIST_FIREBASE_API_KEY has unexpected characters" >&2
  exit 1
fi

mkdir -p "$DIST_DIR"
cat > "$DIST_DIR/config.js" <<EOF
// Generated by CI/CD (scripts/render_web_config.sh). Do not edit.
window.COEXIST_FIREBASE_API_KEY = "${COEXIST_FIREBASE_API_KEY}";
EOF
echo "Rendered $DIST_DIR/config.js"
